15	/// Page-first geometry: dimensions and derived strides for one page.
16	///
17	/// Pure value type — no GPU, no allocation. Shared by `KvPool`, `KvState`, `KvDesc`.
18	#[derive(Clone, Copy, Debug)]
19	pub struct KvLayout {
20	    pub page_size: usize,
21	    pub num_layers: usize,
22	    pub num_kv_heads: usize,
23	    pub head_dim: usize,
24	    /// Elements in one K (or V) block: page_size × num_kv_heads × head_dim.
25	    pub kv_block_len: usize,
26	    /// Elements between layers within a page: the format's values per token
27	    /// over the page's tokens and heads (K then V for `KvFormat::Split`).
28	    pub layer_stride: usize,
29	    /// Elements per page (all layers): num_layers × layer_stride.
30	    pub page_stride: usize,
31	    pub storage: KvStorage,
32	    pub format: KvFormat,
33	}
34	
35	impl KvLayout {
36	    pub fn new(
37	        num_layers: usize,
38	        num_kv_heads: usize,
39	        head_dim: usize,
40	        page_size: usize,
41	    ) -> anyhow::Result<Self> {
42	        Self::with_storage(
43	            num_layers,
44	            num_kv_heads,
45	            head_dim,
46	            page_size,
47	            KvStorage::Bf16,
48	        )
49	    }
50	
51	    pub fn with_storage(
52	        num_layers: usize,
53	        num_kv_heads: usize,
54	        head_dim: usize,
55	        page_size: usize,
56	        storage: KvStorage,
57	    ) -> anyhow::Result<Self> {
58	        Self::with_storage_and_format(
59	            num_layers,
60	            num_kv_heads,
61	            head_dim,
62	            page_size,
63	            storage,
64	            KvFormat::Split,
65	        )
66	    }
67	
68	    pub fn with_storage_and_format(
69	        num_layers: usize,
70	        num_kv_heads: usize,
71	        head_dim: usize,
72	        page_size: usize,
73	        storage: KvStorage,
74	        format: KvFormat,
75	    ) -> anyhow::Result<Self> {
76	        let (kv_block_len, layer_stride, page_stride) = pegainfer_kernels::paged_kv::derive_strides(
77	            page_size,
78	            num_kv_heads,
79	            head_dim,
