86	                 {num_layers} layers x {num_kv_heads} heads x {page_size} page"
87	            )
88	        })?;
89	        Ok(Self {
90	            page_size,
91	            num_layers,
92	            num_kv_heads,
93	            head_dim,
94	            kv_block_len,
95	            layer_stride,
96	            page_stride,
97	            storage,
98	            format,
99	        })
100	    }
