117	struct KvPoolInner {
118	    pool: PagePool,
119	    buffer: CudaSlice<bf16>,
120	    layout: KvLayout,
121	    /// Reserved page for bucket CUDA Graph padding. FlashInfer metadata for
122	    /// padding slots points here with seq_len=1. KV append writes harmless
123	    /// garbage; attention output is discarded.
124	    padding_permit: OwnedPagePermit,
125	}
126	
127	/// Shared KV backing storage with page-based allocation.
128	///
129	/// Owns a single GPU buffer in page-first layout: each page is a contiguous
130	/// chunk holding all layers' K and V for `page_size` tokens.
131	///
132	/// ```text
133	/// page_i: [L0_K | L0_V | L1_K | L1_V | ... | Ln_K | Ln_V]
134	///          └─ page_size × num_kv_heads × head_dim each ─┘
135	/// ```
136	///
137	/// Cheaply cloneable (Arc). Multiple `KvState`s share the same pool.
138	#[derive(Clone)]
139	pub struct KvPool {
140	    inner: Arc<KvPoolInner>,
141	}
142	
143	impl KvPool {
144	    pub fn new(
145	        ctx: &DeviceContext,
146	        num_layers: usize,
147	        num_kv_heads: usize,
148	        head_dim: usize,
149	        page_size: usize,
150	        num_pages: usize,
151	    ) -> Result<Self> {
152	        Self::with_storage(
153	            ctx,
154	            num_layers,
155	            num_kv_heads,
156	            head_dim,
157	            page_size,
158	            num_pages,
159	            KvStorage::Bf16,
160	        )
161	    }
162	
163	    #[allow(clippy::too_many_arguments)]
164	    pub fn with_storage(
165	        ctx: &DeviceContext,
166	        num_layers: usize,
167	        num_kv_heads: usize,
168	        head_dim: usize,
169	        page_size: usize,
170	        num_pages: usize,
171	        storage: KvStorage,
172	    ) -> Result<Self> {
173	        Self::with_storage_and_format(
174	            ctx,
175	            num_layers,
176	            num_kv_heads,
177	            head_dim,
178	            page_size,
179	            num_pages,
180	            storage,
181	            KvFormat::Split,
182	        )
183	    }
184	
185	    #[allow(clippy::too_many_arguments)]
186	    pub fn with_storage_and_format(
187	        ctx: &DeviceContext,
188	        num_layers: usize,
189	        num_kv_heads: usize,
190	        head_dim: usize,
191	        page_size: usize,
192	        num_pages: usize,
193	        storage: KvStorage,
194	        format: KvFormat,
195	    ) -> Result<Self> {
196	        let layout = KvLayout::with_storage_and_format(
197	            num_layers,
198	            num_kv_heads,
199	            head_dim,
200	            page_size,
201	            storage,
202	            format,
203	        )?;
204	        let total_elements = num_pages.checked_mul(layout.page_stride).ok_or_else(|| {
205	            anyhow::anyhow!(
206	                "KvPool geometry overflows: {num_pages} pages x {} elements per page",
207	                layout.page_stride
208	            )
209	        })?;
210	        // The allocator multiplies by the element size unchecked; answer
211	        // for the byte domain here, before it does.
212	        let total_bytes = total_elements
213	            .checked_mul(layout.storage.elem_bytes())
214	            .ok_or_else(|| {
215	                anyhow::anyhow!(
216	                    "KvPool geometry overflows the byte domain: {total_elements} elements"
217	                )
218	            })?;
219	        let backing_slots = total_bytes.div_ceil(std::mem::size_of::<bf16>());
220	
221	        let buffer: CudaSlice<bf16> = ctx
222	            .stream
223	            .alloc_zeros(backing_slots)
224	            .map_err(|e| anyhow::anyhow!("KvPool alloc failed: {e}"))?;
225	
226	        let pool = PagePool::new(num_pages);
227	        let padding_permit = pool
228	            .try_acquire_many(1)
229	            .expect("pool must have at least 1 page for padding");
230	
231	        Ok(Self {
232	            inner: Arc::new(KvPoolInner {
233	                pool,
234	                buffer,
235	                layout,
236	                padding_permit,
237	            }),
238	        })
239	    }
240	
241	    /// Create an empty per-request KV state.
242	    pub fn alloc(&self) -> KvState {
243	        KvState {
244	            permit: self.inner.pool.try_acquire_many(0).expect("zero acquire"),
245	            seq_len: 0,
246	            pool: self.clone(),
247	        }
248	    }
