250	    pub fn layout(&self) -> &KvLayout {
251	        &self.inner.layout
252	    }
253	
254	    /// Every state in this pool is a view into this one buffer, so an
255	    /// executor can hold the pool and take page metadata from a plan rather
256	    /// than from a request's state.
257	    pub fn buffer(&self) -> &CudaSlice<bf16> {
258	        &self.inner.buffer
259	    }
260	
261	    pub fn capacity_pages(&self) -> usize {
262	        self.inner.pool.capacity_pages()
263	    }
264	
265	    pub fn available_pages(&self) -> usize {
266	        self.inner.pool.available_pages()
267	    }
268	
269	    /// Page index reserved for bucket CUDA Graph padding.
270	    pub fn padding_page_id(&self) -> i32 {
271	        self.inner.padding_permit.pages()[0].index() as i32
272	    }
273	
274	    /// The schedule half of an atomic multi-pool admission: reserve from
275	    /// every pool first, commit only when all reservations hold, and let a
276	    /// failure roll the rest back by drop. Growing a request's own permit
277	    /// instead cannot be undone.
278	    pub fn try_reserve(&self, pages: usize) -> Option<KvReservation> {
279	        self.inner
280	            .pool
281	            .try_acquire_many(pages)
282	            .map(|permit| KvReservation { permit })
283	    }
284	}
