310	/// Pages needed to hold `token_count` tokens with the given `page_size`.
311	fn pages_needed(token_count: usize, page_size: usize) -> usize {
312	    token_count.div_ceil(page_size)
313	}
314	
315	fn last_page_len_for(token_count: usize, page_size: usize) -> usize {
316	    if token_count == 0 {
317	        0
318	    } else {
319	        let rem = token_count % page_size;
320	        if rem == 0 { page_size } else { rem }
321	    }
322	}
