349	    /// Page ids only mean something against the pool that issued them, so an
350	    /// executor holding a pool must check before indexing its buffer.
351	    pub fn belongs_to(&self, pool: &KvPool) -> bool {
352	        std::sync::Arc::ptr_eq(&self.pool.inner, &pool.inner)
353	    }
