397	    pub fn desc_for_len(&self, seq_len: usize) -> Result<KvDesc<'_>> {
398	        let held = self.permit.len();
399	        let needed = pages_needed(seq_len, self.pool.inner.layout.page_size);
400	        anyhow::ensure!(
401	            held == needed,
402	            "KvState holds {held} pages where {seq_len} tokens need exactly {needed}"
403	        );
404	        Ok(KvDesc {
405	            pages: self.permit.pages(),
406	            last_page_len: last_page_len_for(seq_len, self.pool.inner.layout.page_size),
407	        })
408	    }
