450	    use super::*;
451	
452	    fn test_pool(page_size: usize, num_pages: usize) -> KvPool {
453	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
454	        // Tiny allocation: 1 layer, 1 head, dim=1 — just enough to exercise logic.
455	        KvPool::new(&ctx, 1, 1, 1, page_size, num_pages).expect("KvPool::new failed")
456	    }
457	
458	    #[test]
459	    fn storage_width_sets_backing_capacity() {
460	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
461	        let pages = 3;
462	        let fp8 =
463	            KvPool::with_storage(&ctx, 1, 1, 1, 16, pages, KvStorage::E4m3).expect("fp8 KvPool");
464	        let bf16 =
465	            KvPool::with_storage(&ctx, 1, 1, 1, 16, pages, KvStorage::Bf16).expect("bf16 KvPool");
466	        assert_eq!(
467	            fp8.buffer().len(),
468	            (pages * fp8.layout().page_stride).div_ceil(2)
469	        );
470	        assert_eq!(bf16.buffer().len(), pages * bf16.layout().page_stride);
471	    }
