497	        // 5 pages total: 1 reserved for padding, 4 available for requests
498	        let pool = test_pool(16, 5);
499	        let mut kv = pool.alloc();
500	
501	        // Starts empty
502	        assert_eq!(kv.seq_len(), 0);
503	        let desc = kv.desc();
504	        assert_eq!(desc.num_pages(), 0);
505	        assert_eq!(desc.last_page_len(), 0);
506	
507	        // Prefill 10 tokens: needs 1 page
508	        kv.ensure_capacity(10).unwrap();
509	        kv.advance(10);
510	        assert_eq!(kv.seq_len(), 10);
511	        let desc = kv.desc();
512	        assert_eq!(desc.num_pages(), 1);
513	        assert_eq!(desc.last_page_len(), 10);
514	        assert_eq!(pool.available_pages(), 3);
515	
516	        // Decode to 16: still 1 page, last_page_len=16 (full)
517	        for _ in 10..16 {
518	            kv.ensure_capacity(kv.seq_len() + 1).unwrap();
519	            kv.advance(1);
520	        }
521	        let desc = kv.desc();
522	        assert_eq!(desc.num_pages(), 1);
523	        assert_eq!(desc.last_page_len(), 16);
524	
525	        // One more token crosses page boundary: 2 pages
526	        kv.ensure_capacity(kv.seq_len() + 1).unwrap();
527	        kv.advance(1);
528	        assert_eq!(kv.seq_len(), 17);
529	        let desc = kv.desc();
