30	/// CUDA Graph state for decode path.
31	/// First decode call captures the graph; subsequent calls replay it.
32	///
33	/// Capture and replay both run on the context's *currently active* stream
34	/// ([`active_cu_stream`]) — normally `ctx.stream`, but the thread-local stream
35	/// override used by Green Context SM partitioning redirects them. This matters
36	/// because stream capture binds each kernel node to the execution context of
37	/// the stream it was captured on (CUDA Programming Guide §4.6.5): a graph
38	/// captured on a Green Context decode stream replays on that partition's SMs no
39	/// matter which stream launches it. A `CudaGraphState` is therefore tied to one
40	/// stream — a caller that decodes on more than one stream (full-SM and a green
41	/// partition) must keep one state per stream.
42	pub struct CudaGraphState {
43	    graph: CUgraph,
44	    exec: CUgraphExec,
45	    /// Keeps the CUDA primary context alive for as long as the graph handles
46	    /// exist. The raw `CUgraph`/`CUgraphExec` carry no ownership of their own,
47	    /// so without this anchor the `cuGraphDestroy` in `Drop` would rely on the
48	    /// enclosing struct happening to declare its `CudaSlice` buffers *before*
49	    /// this field. `Drop::drop` runs before the struct's fields are dropped, so
50	    /// holding the `Arc` here guarantees the context outlives the destroy calls
51	    /// regardless of field order. `None` until the first capture instantiates.
52	    ctx_anchor: Option<Arc<CudaContext>>,
53	}
54	
55	// SAFETY: the graph/exec handles are only ever touched from the single
56	// inference thread that owns the model.
57	unsafe impl Send for CudaGraphState {}
58	
59	fn check(result: sys::CUresult, what: &str) -> Result<()> {
60	    if result != sys::CUresult::CUDA_SUCCESS {
61	        anyhow::bail!("{what} failed: {result:?}");
62	    }
63	    Ok(())
64	}
65	
66	impl CudaGraphState {
67	    pub fn new() -> Self {
68	        Self {
69	            graph: std::ptr::null_mut(),
70	            exec: std::ptr::null_mut(),
71	            ctx_anchor: None,
72	        }
73	    }
74	
75	    /// Whether a graph has been captured and instantiated — i.e. whether
76	    /// [`Self::launch_captured`] can replay without running the kernel closure.
77	    pub fn is_captured(&self) -> bool {
78	        !self.exec.is_null()
79	    }
80	
81	    /// Replay the captured graph. Errors if nothing has been captured yet —
82	    /// callers that may hit an uncaptured shape go through
83	    /// [`Self::run_or_capture`] instead.
84	    pub fn launch_captured(&mut self, ctx: &DeviceContext) -> Result<()> {
85	        anyhow::ensure!(
86	            self.is_captured(),
87	            "CUDA graph replay requested before any capture"
88	        );
89	        let stream = active_cu_stream(ctx);
90	        check(
91	            unsafe { sys::cuGraphLaunch(self.exec, stream) },
92	            "cuGraphLaunch",
93	        )
94	    }
95	
96	    /// Run kernel closure directly, or capture into a graph and replay.
97	    ///
98	    /// `kernels` must be a pure GPU kernel sequence — no CPU-GPU sync, no allocation.
99	    pub fn run_or_capture<F>(&mut self, ctx: &DeviceContext, kernels: F) -> Result<()>
100	    where
101	        F: FnOnce() -> Result<()>,
102	    {
103	        self.run_or_capture_synchronized(ctx, |_| {}, kernels)
104	    }
105	
106	    /// Capture, instantiate, and upload — no launch — so a later
107	    /// [`Self::launch_captured`] is a pure enqueue (an un-uploaded exec uploads
108	    /// implicitly on first launch). The upload is stream-ordered: a launch
109	    /// enqueued after it on the same stream is ordered behind it by the
110	    /// driver, so only a launch from a *different* stream needs a
111	    /// synchronization in between.
112	    pub fn capture_only<F>(&mut self, ctx: &DeviceContext, kernels: F) -> Result<()>
113	    where
114	        F: FnOnce() -> Result<()>,
115	    {
116	        anyhow::ensure!(
117	            !self.is_captured(),
118	            "capture_only on an already-captured graph would leak the live exec"
119	        );
120	        let stream = active_cu_stream(ctx);
121	        self.capture_and_instantiate(ctx, stream, &mut |_| {}, kernels)?;
122	        check(
123	            unsafe { sys::cuGraphUpload(self.exec, stream) },
124	            "cuGraphUpload",
125	        )
126	    }
127	
128	    pub fn run_or_capture_synchronized<F, S>(
129	        &mut self,
130	        ctx: &DeviceContext,
131	        mut synchronize: S,
132	        kernels: F,
133	    ) -> Result<()>
134	    where
135	        F: FnOnce() -> Result<()>,
136	        S: FnMut(CudaGraphPhase),
137	    {
138	        let stream = active_cu_stream(ctx);
139	
140	        if !self.exec.is_null() {
141	            synchronize(CudaGraphPhase::BeforeLaunch);
142	            check(
143	                unsafe { sys::cuGraphLaunch(self.exec, stream) },
144	                "cuGraphLaunch",
145	            )?;
146	            synchronize(CudaGraphPhase::AfterLaunch);
147	            return Ok(());
148	        }
149	
150	        self.capture_and_instantiate(ctx, stream, &mut synchronize, kernels)?;
151	
152	        synchronize(CudaGraphPhase::BeforeLaunch);
153	        check(
154	            unsafe { sys::cuGraphLaunch(self.exec, stream) },
155	            "cuGraphLaunch first launch",
156	        )?;
157	        synchronize(CudaGraphPhase::AfterLaunch);
158	        Ok(())
159	    }
160	
161	    fn capture_and_instantiate<F, S>(
162	        &mut self,
163	        ctx: &DeviceContext,
164	        stream: sys::CUstream,
165	        synchronize: &mut S,
166	        kernels: F,
167	    ) -> Result<()>
168	    where
169	        F: FnOnce() -> Result<()>,
170	        S: FnMut(CudaGraphPhase),
171	    {
172	        debug!("Capturing CUDA Graph for decode path...");
173	        synchronize(CudaGraphPhase::BeforeBeginCapture);
174	        check(
175	            unsafe { sys::cuStreamBeginCapture_v2(stream, CU_STREAM_CAPTURE_MODE_THREAD_LOCAL) },
176	            "cuStreamBeginCapture",
177	        )?;
178	        synchronize(CudaGraphPhase::AfterBeginCapture);
179	
180	        // On kernel error, end the in-progress capture so the stream is not left
181	        // stuck in the capturing state, then propagate the original error.
182	        if let Err(e) = kernels() {
183	            let mut aborted: CUgraph = std::ptr::null_mut();
184	            unsafe { sys::cuStreamEndCapture(stream, &raw mut aborted) };
185	            if !aborted.is_null() {
186	                unsafe { sys::cuGraphDestroy(aborted) };
187	            }
188	            return Err(e);
189	        }
190	
191	        synchronize(CudaGraphPhase::BeforeEndCapture);
192	        let mut graph: CUgraph = std::ptr::null_mut();
193	        check(
194	            unsafe { sys::cuStreamEndCapture(stream, &raw mut graph) },
195	            "cuStreamEndCapture",
196	        )?;
197	        let mut exec: CUgraphExec = std::ptr::null_mut();
198	        check(
199	            unsafe {
200	                sys::cuGraphInstantiateWithFlags(
201	                    &raw mut exec,
202	                    graph,
203	                    CUDA_GRAPH_INSTANTIATE_FLAG_AUTO_FREE_ON_LAUNCH as u64,
204	                )
205	            },
206	            "cuGraphInstantiateWithFlags",
207	        )?;
208	        self.graph = graph;
209	        self.exec = exec;
210	        self.ctx_anchor = Some(ctx.ctx.clone());
211	        synchronize(CudaGraphPhase::AfterEndCapture);
212	        debug!("CUDA Graph captured successfully");
213	        Ok(())
214	    }
215	}
216	
217	impl Default for CudaGraphState {
218	    fn default() -> Self {
219	        Self::new()
220	    }
221	}
222	
223	impl Drop for CudaGraphState {
224	    fn drop(&mut self) {
225	        unsafe {
226	            if !self.exec.is_null() {
227	                sys::cuGraphExecDestroy(self.exec);
228	            }
229	            if !self.graph.is_null() {
230	                sys::cuGraphDestroy(self.graph);
231	            }
232	        }
233	    }
234	}
