292	impl KvReservation {
293	    /// Append this reservation's page ids to a row the caller owns. A sliding
294	    /// state rebuilds that row every step, so the pages land in one buffer
295	    /// instead of one `Vec` per reservation.
296	    pub fn extend_page_indices_i32(&self, row: &mut Vec<i32>) {
297	        row.extend(self.permit.pages().iter().map(|p| p.index() as i32));
298	    }
