301	/// Per-request KV state. Parallels `RecurrentState` for linear attention.
302	///
303	/// Holds an RAII page permit that auto-returns pages on drop.
304	pub struct KvState {
305	    permit: OwnedPagePermit,
306	    seq_len: usize,
307	    pool: KvPool,
308	}
309	
310	/// Pages needed to hold `token_count` tokens with the given `page_size`.
311	fn pages_needed(token_count: usize, page_size: usize) -> usize {
312	    token_count.div_ceil(page_size)
313	}
314	
315	fn last_page_len_for(token_count: usize, page_size: usize) -> usize {
316	    if token_count == 0 {
317	        0
318	    } else {
319	        let rem = token_count % page_size;
320	        if rem == 0 { page_size } else { rem }
321	    }
322	}
323	
324	impl KvState {
325	    pub fn seq_len(&self) -> usize {
326	        self.seq_len
327	    }
328	
329	    pub fn last_page_len(&self) -> usize {
330	        last_page_len_for(self.seq_len, self.pool.inner.layout.page_size)
331	    }
332	
333	    /// Page indices as i32 for GPU upload.
334	    pub fn page_indices_i32(&self) -> Vec<i32> {
335	        let mut pages = Vec::with_capacity(self.permit.pages().len());
336	        self.extend_page_indices_i32(&mut pages);
337	        pages
338	    }
339	
340	    /// Append page indices to caller-owned planning storage.
341	    pub fn extend_page_indices_i32(&self, pages: &mut Vec<i32>) {
342	        pages.extend(self.permit.pages().iter().map(|p| p.index() as i32));
343	    }
344	
345	    pub fn buffer(&self) -> &CudaSlice<bf16> {
346	        &self.pool.inner.buffer
347	    }
348	
349	    /// Page ids only mean something against the pool that issued them, so an
350	    /// executor holding a pool must check before indexing its buffer.
351	    pub fn belongs_to(&self, pool: &KvPool) -> bool {
352	        std::sync::Arc::ptr_eq(&self.pool.inner, &pool.inner)
353	    }
354	
355	    pub fn layout(&self) -> &KvLayout {
356	        &self.pool.inner.layout
357	    }
358	
359	    /// Ensure capacity for at least `token_count` tokens total.
360	    pub fn ensure_capacity(&mut self, token_count: usize) -> Result<()> {
361	        let needed = pages_needed(token_count, self.pool.inner.layout.page_size);
362	        let held = self.permit.len();
363	        if needed <= held {
364	            return Ok(());
365	        }
366	        let grow = needed - held;
367	        if !self.permit.try_grow(grow) {
368	            bail!(
369	                "KvState: out of pages (need {grow} more, {} available)",
370	                self.pool.available_pages()
371	            );
372	        }
373	        Ok(())
374	    }
375	
376	    pub fn held_pages(&self) -> usize {
377	        self.permit.len()
378	    }
379	
380	    /// The apply half of an atomic multi-pool admission. The reservation must
381	    /// come from this state's pool, which the permit merge enforces.
382	    pub fn commit_reservation(&mut self, reservation: KvReservation) {
383	        self.permit.absorb(reservation.permit);
384	    }
385	
386	    pub fn advance(&mut self, count: usize) {
387	        self.seq_len += count;
388	    }
389	
390	    pub fn desc(&self) -> KvDesc<'_> {
391	        KvDesc {
392	            pages: self.permit.pages(),
393	            last_page_len: self.last_page_len(),
394	        }
395	    }
396	
397	    pub fn desc_for_len(&self, seq_len: usize) -> Result<KvDesc<'_>> {
398	        let held = self.permit.len();
399	        let needed = pages_needed(seq_len, self.pool.inner.layout.page_size);
400	        anyhow::ensure!(
401	            held == needed,
402	            "KvState holds {held} pages where {seq_len} tokens need exactly {needed}"
403	        );
404	        Ok(KvDesc {
405	            pages: self.permit.pages(),
406	            last_page_len: last_page_len_for(seq_len, self.pool.inner.layout.page_size),
407	        })
408	    }
409	
410	    /// Reset for a new request: return all pages, zero seq_len.
411	    #[cfg(test)]
412	    fn reset(&mut self) {
413	        self.permit = self
414	            .pool
415	            .inner
416	            .pool
417	            .try_acquire_many(0)
418	            .expect("zero acquire");
419	        self.seq_len = 0;
420	    }
421	}
