449	mod tests {
450	    use super::*;
451	
452	    fn test_pool(page_size: usize, num_pages: usize) -> KvPool {
453	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
454	        // Tiny allocation: 1 layer, 1 head, dim=1 — just enough to exercise logic.
455	        KvPool::new(&ctx, 1, 1, 1, page_size, num_pages).expect("KvPool::new failed")
456	    }
457	
458	    #[test]
459	    fn storage_width_sets_backing_capacity() {
460	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
461	        let pages = 3;
462	        let fp8 =
463	            KvPool::with_storage(&ctx, 1, 1, 1, 16, pages, KvStorage::E4m3).expect("fp8 KvPool");
464	        let bf16 =
465	            KvPool::with_storage(&ctx, 1, 1, 1, 16, pages, KvStorage::Bf16).expect("bf16 KvPool");
466	        assert_eq!(
467	            fp8.buffer().len(),
468	            (pages * fp8.layout().page_stride).div_ceil(2)
469	        );
470	        assert_eq!(bf16.buffer().len(), pages * bf16.layout().page_stride);
471	    }
472	
473	    #[test]
474	    fn stride_geometry_qwen35() {
475	        // Qwen3.5-4B: 8 full attn layers, 4 KV heads, head_dim=256, page_size=16
476	        let l = KvLayout::new(8, 4, 256, 16).expect("layout");
477	
478	        assert_eq!(l.kv_block_len, 16 * 4 * 256); // 16384 elements
479	        assert_eq!(l.layer_stride, 2 * 16384); // 32768 (K + V)
480	        assert_eq!(l.page_stride, 8 * 32768); // 262144 per page
481	        // bytes: 262144 * 2 = 524288 = 512 KB per page
482	        assert_eq!(l.page_stride * 2, 512 * 1024);
483	    }
484	
485	    #[test]
486	    fn stride_geometry_qwen3() {
487	        // Qwen3-4B: 36 full attn layers, 4 KV heads, head_dim=128, page_size=16
488	        let l = KvLayout::new(36, 4, 128, 16).expect("layout");
489	
490	        // 36 layers × 16384 = 589824 elements per page
491	        assert_eq!(l.page_stride, 589_824);
492	        // bytes: ~1.125 MB per page
493	    }
494	
495	    #[test]
496	    fn kv_state_lifecycle() {
497	        // 5 pages total: 1 reserved for padding, 4 available for requests
498	        let pool = test_pool(16, 5);
499	        let mut kv = pool.alloc();
500	
501	        // Starts empty
502	        assert_eq!(kv.seq_len(), 0);
503	        let desc = kv.desc();
504	        assert_eq!(desc.num_pages(), 0);
505	        assert_eq!(desc.last_page_len(), 0);
506	
507	        // Prefill 10 tokens: needs 1 page
508	        kv.ensure_capacity(10).unwrap();
509	        kv.advance(10);
510	        assert_eq!(kv.seq_len(), 10);
511	        let desc = kv.desc();
512	        assert_eq!(desc.num_pages(), 1);
513	        assert_eq!(desc.last_page_len(), 10);
514	        assert_eq!(pool.available_pages(), 3);
515	
516	        // Decode to 16: still 1 page, last_page_len=16 (full)
517	        for _ in 10..16 {
518	            kv.ensure_capacity(kv.seq_len() + 1).unwrap();
519	            kv.advance(1);
520	        }
521	        let desc = kv.desc();
522	        assert_eq!(desc.num_pages(), 1);
523	        assert_eq!(desc.last_page_len(), 16);
524	
525	        // One more token crosses page boundary: 2 pages
526	        kv.ensure_capacity(kv.seq_len() + 1).unwrap();
527	        kv.advance(1);
528	        assert_eq!(kv.seq_len(), 17);
529	        let desc = kv.desc();
530	        assert_eq!(desc.num_pages(), 2);
531	        assert_eq!(desc.last_page_len(), 1);
532	        assert_eq!(pool.available_pages(), 2);
533	
534	        // Reset returns all pages
535	        kv.reset();
536	        assert_eq!(kv.seq_len(), 0);
537	        assert_eq!(pool.available_pages(), 4);
538	    }
539	
540	    #[test]
541	    fn kv_state_out_of_pages() {
542	        // 3 pages total: 1 padding, 2 available → 32 tokens max
543	        let pool = test_pool(16, 3);
544	        let mut kv = pool.alloc();
545	
546	        kv.ensure_capacity(32).unwrap(); // exactly fits 2 pages
547	        assert!(kv.ensure_capacity(33).is_err()); // needs 3rd page
548	    }
549	
550	    #[test]
551	    fn kv_state_drop_returns_pages() {
552	        // 5 pages total: 1 padding, 4 available
553	        let pool = test_pool(16, 5);
554	        {
555	            let mut kv = pool.alloc();
556	            kv.ensure_capacity(20).unwrap(); // 2 pages
557	            kv.advance(20);
558	            assert_eq!(pool.available_pages(), 2);
559	        }
560	        // Drop returns pages
561	        assert_eq!(pool.available_pages(), 4);
562	    }
563	}
