102	    const MIN_DRIVER_API_VERSION: i32 = 12_030;
103	
104	    let mut version = 0i32;
105	    check(
106	        unsafe { sys::cuDriverGetVersion(&raw mut version) },
107	        "cuDriverGetVersion",
108	    )?;
109	    ensure!(
110	        version >= MIN_DRIVER_API_VERSION,
111	        "--dump-graph-png requires CUDA driver API 12.3 or newer for kernel names; found {}",
112	        format_driver_api_version(version)
113	    );
114	    Ok(())
115	}
