141	        let dot_path = png_path.with_extension("dot");
142	        std::fs::write(&dot_path, graph.detailed_dot())
143	            .with_context(|| format!("write detailed CUDA Graph DOT to {}", dot_path.display()))?;
144	        render_png(&graph.human_dot(title), png_path)?;
145	        Ok(CudaGraphDumpSummary {
146	            nodes: graph.nodes.len(),
147	            edges: graph.edges.len(),
148	            kernels: graph
149	                .nodes
150	                .iter()
151	                .filter(|node| matches!(&node.kind, GraphNodeKind::Kernel { .. }))
152	                .count(),
153	            dot_path,
154	            png_path: png_path.to_path_buf(),
155	        })
156	    }
