158	    fn inspect(&self) -> Result<GraphDescription> {
159	        let handles = graph_nodes(self.graph)?;
160	        let handle_to_index: HashMap<usize, usize> = handles
161	            .iter()
162	            .enumerate()
163	            .map(|(index, &handle)| (handle as usize, index))
164	            .collect();
165	        let raw_kinds = handles
166	            .iter()
167	            .map(|&handle| inspect_node(handle))
168	            .collect::<Result<Vec<_>>>()?;
169	        let symbols = raw_kinds
170	            .iter()
171	            .filter_map(|kind| match kind {
172	                RawNodeKind::Kernel { raw_symbol, .. } => Some(raw_symbol.as_str()),
173	                RawNodeKind::Other { .. } => None,
174	            })
175	            .collect::<Vec<_>>();
176	        let demangled = demangle(&symbols)?;
177	        let mut demangled = demangled.into_iter();
178	        let nodes = raw_kinds
179	            .into_iter()
180	            .map(|kind| GraphNode {
181	                kind: match kind {
182	                    RawNodeKind::Kernel {
183	                        raw_symbol,
184	                        grid,
185	                        block,
186	                        dynamic_shared_mem_bytes,
187	                    } => GraphNodeKind::Kernel {
188	                        raw_symbol,
189	                        demangled: demangled
190	                            .next()
191	                            .expect("one demangled name per kernel node"),
192	                        grid,
193	                        block,
194	                        dynamic_shared_mem_bytes,
195	                    },
196	                    RawNodeKind::Other { node_type } => GraphNodeKind::Other { node_type },
197	                },
198	            })
199	            .collect();
200	        let edges = graph_edges(self.graph)?
201	            .into_iter()
202	            .map(|(from, to, data)| {
203	                let from = handle_to_index
204	                    .get(&(from as usize))
205	                    .copied()
206	                    .context("CUDA graph edge source is absent from the node list")?;
207	                let to = handle_to_index
208	                    .get(&(to as usize))
209	                    .copied()
210	                    .context("CUDA graph edge destination is absent from the node list")?;
211	                Ok(GraphEdge {
212	                    from,
213	                    to,
214	                    from_port: data.from_port,
215	                    to_port: data.to_port,
216	                    dependency_type: data.type_,
217	                })
218	            })
219	            .collect::<Result<Vec<_>>>()?;
220	        Ok(GraphDescription { nodes, edges })
221	    }
222	}
