19	use super::check;
20	
21	mod render;
22	
23	#[derive(Clone, Debug)]
24	pub struct CudaGraphDumpSummary {
25	    pub nodes: usize,
26	    pub edges: usize,
27	    pub kernels: usize,
28	    pub dot_path: PathBuf,
29	    pub png_path: PathBuf,
30	}
31	
32	struct GraphDescription {
33	    nodes: Vec<GraphNode>,
34	    edges: Vec<GraphEdge>,
35	}
36	
37	struct GraphNode {
38	    kind: GraphNodeKind,
39	}
40	
41	#[derive(Clone, Copy)]
42	struct GraphEdge {
43	    from: usize,
44	    to: usize,
45	    from_port: u8,
46	    to_port: u8,
47	    dependency_type: u8,
48	}
49	
50	impl GraphEdge {
51	    #[cfg(test)]
52	    fn ordinary(from: usize, to: usize) -> Self {
53	        Self {
54	            from,
55	            to,
56	            from_port: 0,
57	            to_port: 0,
58	            dependency_type: 0,
59	        }
60	    }
61	}
62	
63	enum GraphNodeKind {
64	    Kernel {
65	        raw_symbol: String,
66	        demangled: String,
67	        grid: [u32; 3],
68	        block: [u32; 3],
69	        dynamic_shared_mem_bytes: u32,
70	    },
71	    Other {
72	        node_type: String,
73	    },
74	}
75	
76	pub fn validate_graph_dump_request(png_path: &Path) -> Result<()> {
77	    ensure!(
78	        png_path
79	            .extension()
80	            .and_then(|extension| extension.to_str())
81	            .is_some_and(|extension| extension.eq_ignore_ascii_case("png")),
82	        "--dump-graph-png expects a .png output path, got {}",
83	        png_path.display()
84	    );
85	    let parent = png_path
86	        .parent()
87	        .filter(|parent| !parent.as_os_str().is_empty())
88	        .unwrap_or_else(|| Path::new("."));
89	    std::fs::create_dir_all(parent).with_context(|| {
90	        format!(
91	            "create CUDA Graph dump output directory {}",
92	            parent.display()
93	        )
94	    })?;
95	    require_graph_dump_driver()?;
96	    require_tool("dot", &["-Tpng:cairo"], "Graphviz Cairo PNG renderer")?;
97	    require_tool("c++filt", &["--version"], "C++ demangler")?;
98	    Ok(())
99	}
100	
101	fn require_graph_dump_driver() -> Result<()> {
102	    const MIN_DRIVER_API_VERSION: i32 = 12_030;
103	
104	    let mut version = 0i32;
105	    check(
106	        unsafe { sys::cuDriverGetVersion(&raw mut version) },
107	        "cuDriverGetVersion",
108	    )?;
109	    ensure!(
110	        version >= MIN_DRIVER_API_VERSION,
111	        "--dump-graph-png requires CUDA driver API 12.3 or newer for kernel names; found {}",
112	        format_driver_api_version(version)
113	    );
114	    Ok(())
115	}
116	
117	fn format_driver_api_version(version: i32) -> String {
118	    format!("{}.{}", version / 1000, version % 1000 / 10)
119	}
120	
121	fn require_tool(program: &str, args: &[&str], description: &str) -> Result<()> {
122	    let output = Command::new(program)
123	        .args(args)
124	        .output()
125	        .with_context(|| format!("{description} `{program}` is required for CUDA Graph export"))?;
126	    ensure!(
127	        output.status.success(),
128	        "{description} `{program}` check failed: {}",
129	        String::from_utf8_lossy(&output.stderr).trim()
130	    );
131	    Ok(())
132	}
