236	fn graph_nodes(graph: sys::CUgraph) -> Result<Vec<CUgraphNode>> {
237	    let mut count = 0usize;
238	    check(
239	        unsafe { sys::cuGraphGetNodes(graph, std::ptr::null_mut(), &raw mut count) },
240	        "cuGraphGetNodes(count)",
241	    )?;
242	    let mut nodes = vec![std::ptr::null_mut(); count];
243	    check(
244	        unsafe { sys::cuGraphGetNodes(graph, nodes.as_mut_ptr(), &raw mut count) },
245	        "cuGraphGetNodes(nodes)",
246	    )?;
247	    nodes.truncate(count);
248	    Ok(nodes)
