251	fn graph_edges(
252	    graph: sys::CUgraph,
253	) -> Result<Vec<(CUgraphNode, CUgraphNode, sys::CUgraphEdgeData)>> {
254	    let mut count = 0usize;
255	    check(
256	        unsafe {
257	            sys::cuGraphGetEdges_v2(
258	                graph,
259	                std::ptr::null_mut(),
260	                std::ptr::null_mut(),
261	                std::ptr::null_mut(),
262	                &raw mut count,
263	            )
264	        },
265	        "cuGraphGetEdges(count)",
266	    )?;
267	    let mut from = vec![std::ptr::null_mut(); count];
268	    let mut to = vec![std::ptr::null_mut(); count];
269	    let mut data = vec![
270	        sys::CUgraphEdgeData {
271	            from_port: 0,
272	            to_port: 0,
273	            type_: 0,
274	            reserved: [0; 5],
275	        };
276	        count
277	    ];
278	    check(
279	        unsafe {
280	            sys::cuGraphGetEdges_v2(
281	                graph,
282	                from.as_mut_ptr(),
283	                to.as_mut_ptr(),
284	                data.as_mut_ptr(),
285	                &raw mut count,
286	            )
287	        },
288	        "cuGraphGetEdges(edges)",
289	    )?;
290	    Ok(from
291	        .into_iter()
292	        .zip(to)
293	        .zip(data)
294	        .take(count)
295	        .map(|((from, to), data)| (from, to, data))
296	        .collect())
