299	fn inspect_node(node: CUgraphNode) -> Result<RawNodeKind> {
300	    let mut node_type = std::mem::MaybeUninit::uninit();
301	    check(
302	        unsafe { sys::cuGraphNodeGetType(node, node_type.as_mut_ptr()) },
303	        "cuGraphNodeGetType",
304	    )?;
305	    let node_type = unsafe { node_type.assume_init() };
306	    if node_type != sys::CUgraphNodeType::CU_GRAPH_NODE_TYPE_KERNEL {
307	        return Ok(RawNodeKind::Other {
308	            node_type: format!("{node_type:?}")
309	                .trim_start_matches("CU_GRAPH_NODE_TYPE_")
310	                .to_ascii_lowercase(),
311	        });
312	    }
313	
314	    let mut params = std::mem::MaybeUninit::<sys::CUDA_KERNEL_NODE_PARAMS>::zeroed();
315	    check(
316	        unsafe { sys::cuGraphKernelNodeGetParams_v2(node, params.as_mut_ptr()) },
317	        "cuGraphKernelNodeGetParams",
318	    )?;
319	    let params = unsafe { params.assume_init() };
320	    ensure!(
321	        !params.func.is_null(),
322	        "CUDA graph kernel node has no CUfunction"
323	    );
324	    let mut name = std::ptr::null();
325	    check(
326	        unsafe { sys::cuFuncGetName(&raw mut name, params.func) },
327	        "cuFuncGetName",
328	    )?;
329	    ensure!(!name.is_null(), "cuFuncGetName returned a null name");
330	    let raw_symbol = unsafe { CStr::from_ptr(name) }
331	        .to_str()
332	        .context("CUDA kernel name is not UTF-8")?
333	        .to_owned();
334	    Ok(RawNodeKind::Kernel {
335	        raw_symbol,
336	        grid: [params.gridDimX, params.gridDimY, params.gridDimZ],
337	        block: [params.blockDimX, params.blockDimY, params.blockDimZ],
338	        dynamic_shared_mem_bytes: params.sharedMemBytes,
339	    })
340	}
