342	fn demangle(symbols: &[&str]) -> Result<Vec<String>> {
343	    if symbols.is_empty() {
344	        return Ok(Vec::new());
345	    }
346	    let child = Command::new("c++filt")
347	        .stdin(Stdio::piped())
348	        .stdout(Stdio::piped())
349	        .stderr(Stdio::piped())
350	        .spawn()
351	        .context("spawn C++ demangler `c++filt`")?;
352	    let mut input = String::new();
353	    for symbol in symbols {
354	        writeln!(input, "{symbol}").expect("writing to a String cannot fail");
355	    }
356	    let output = communicate(child, input, "c++filt")?;
357	    ensure!(
358	        output.status.success(),
359	        "c++filt failed: {}",
360	        String::from_utf8_lossy(&output.stderr).trim()
361	    );
362	    let names = String::from_utf8(output.stdout)
363	        .context("c++filt output is not UTF-8")?
364	        .lines()
365	        .map(str::to_owned)
366	        .collect::<Vec<_>>();
367	    ensure!(
368	        names.len() == symbols.len(),
369	        "c++filt returned {} names for {} symbols",
370	        names.len(),
371	        symbols.len()
372	    );
373	    Ok(names)
374	}
