377	    let child = Command::new("dot")
378	        .args(["-Tpng:cairo", "-Gdpi=192", "-o"])
379	        .arg(png_path)
380	        .stdin(Stdio::piped())
381	        .stdout(Stdio::null())
382	        .stderr(Stdio::piped())
383	        .spawn()
384	        .context("spawn Graphviz `dot`")?;
385	    let output = communicate(child, dot.to_owned(), "Graphviz")?;
386	    ensure!(
387	        output.status.success(),
388	        "Graphviz failed to render {}: {}",
389	        png_path.display(),
390	        String::from_utf8_lossy(&output.stderr).trim()
391	    );
392	    Ok(())
393	}
394	
395	fn communicate(mut child: Child, input: String, program: &'static str) -> Result<Output> {
396	    let mut stdin = child
397	        .stdin
398	        .take()
399	        .with_context(|| format!("open {program} stdin"))?;
400	    // Whole-step graphs are larger than an OS pipe. Feed stdin concurrently
401	    // while `wait_with_output` drains stdout/stderr, so neither side can fill
402	    // a pipe while waiting for the other side to make progress.
403	    let writer = std::thread::spawn(move || stdin.write_all(input.as_bytes()));
404	    let output = child
405	        .wait_with_output()
406	        .with_context(|| format!("wait for {program}"))?;
407	    let write_result = writer
408	        .join()
409	        .map_err(|_| anyhow::anyhow!("{program} stdin writer panicked"))?;
410	    if output.status.success() {
411	        write_result.with_context(|| format!("write input to {program}"))?;
412	    }
413	    Ok(output)
414	}
