416	impl GraphDescription {
417	    fn detailed_dot(&self) -> String {
418	        let mut dot = String::from("digraph cuda_graph_detailed {\n");
419	        dot.push_str("  graph [rankdir=TB];\n  node [shape=box];\n");
420	        for (index, node) in self.nodes.iter().enumerate() {
421	            let label = match &node.kind {
422	                GraphNodeKind::Kernel {
423	                    raw_symbol,
424	                    demangled,
425	                    grid,
426	                    block,
427	                    dynamic_shared_mem_bytes,
428	                } => format!(
429	                    "id={index}\\ntype=kernel\\nname={}\\nraw_symbol={}\\ngrid={}\\nblock={}\\ndynamic_shared_mem_bytes={dynamic_shared_mem_bytes}",
430	                    dot_escape(demangled),
431	                    dot_escape(raw_symbol),
432	                    dims(*grid),
433	                    dims(*block),
434	                ),
435	                GraphNodeKind::Other { node_type } => {
436	                    format!("id={index}\\ntype={}", dot_escape(node_type))
437	                }
438	            };
439	            let _ = writeln!(dot, "  n{index} [label=\"{label}\"];");
440	        }
441	        for edge in &self.edges {
442	            let _ = writeln!(
443	                dot,
444	                "  n{} -> n{} [label=\"from_port={}\\nto_port={}\\ndependency_type={}\"];",
445	                edge.from,
446	                edge.to,
447	                edge.from_port,
448	                edge.to_port,
449	                dependency_type_name(edge.dependency_type),
450	            );
451	        }
452	        dot.push_str("}\n");
453	        dot
454	    }
455	}
