55	    pub(super) fn human_dot(&self, title: &str) -> String {
56	        let mut indegree = vec![0usize; self.nodes.len()];
57	        let mut outdegree = vec![0usize; self.nodes.len()];
58	        for edge in &self.edges {
59	            outdegree[edge.from] += 1;
60	            indegree[edge.to] += 1;
61	        }
62	
63	        let mut dot = String::from("digraph cuda_graph {\n");
64	        let _ = writeln!(
65	            dot,
66	            "  graph [rankdir=TB, bgcolor=\"white\", pad=0.2, nodesep=0.25, ranksep=0.35, fontname=\"Helvetica\", label=\"{}\", labelloc=t, fontsize=18];",
67	            dot_escape(title)
68	        );
69	        dot.push_str(
70	            "  node [shape=box, style=\"rounded,filled\", color=\"#374151\", \
71	             fontname=\"Helvetica\", fontsize=10, margin=\"0.12,0.08\"];\n",
72	        );
73	        dot.push_str("  edge [color=\"#6B7280\", arrowsize=0.6];\n");
74	        let repeated = self.repeated_dag_runs();
75	        let mut cursor = 0usize;
76	        for (run_index, &run) in repeated.iter().enumerate() {
77	            for index in cursor..run.start {
78	                self.write_human_node(&mut dot, index, indegree[index], outdegree[index]);
79	            }
80	            self.write_repeated_run(&mut dot, run_index, run, &indegree, &outdegree);
81	            cursor = run.end();
82	        }
83	        for index in cursor..self.nodes.len() {
84	            self.write_human_node(&mut dot, index, indegree[index], outdegree[index]);
85	        }
86	
87	        let mut written = HashSet::new();
88	        for edge in &self.edges {
89	            let from_run = run_membership(edge.from, &repeated);
90	            let to_run = run_membership(edge.to, &repeated);
91	            if matches!((from_run, to_run), (Some((left, left_copy, _)), Some((right, right_copy, _))) if left == right && left_copy != right_copy)
92	            {
93	                continue;
94	            }
95	            let projected = HumanEdge {
96	                from: project_node(edge.from, from_run, &repeated),
97	                to: project_node(edge.to, to_run, &repeated),
98	                from_port: edge.from_port,
99	                to_port: edge.to_port,
100	                dependency_type: edge.dependency_type,
101	                after_repetitions: from_run.and_then(|(run_index, copy, _)| {
102	                    let run = repeated[run_index];
103	                    (copy + 1 == run.repetitions
104	                        && to_run.is_none_or(|(to_run_index, _, _)| to_run_index != run_index))
105	                    .then_some(run.repetitions)
106	                }),
107	            };
108	            if projected.from != projected.to && written.insert(projected) {
109	                write_human_edge(&mut dot, projected);
110	            }
111	        }
112	        dot.push_str("}\n");
113	        dot
114	    }
