116	    fn write_human_node(&self, dot: &mut String, index: usize, indegree: usize, outdegree: usize) {
117	        let fill = node_color(indegree, outdegree);
118	        let label = match &self.nodes[index].kind {
119	            GraphNodeKind::Kernel {
120	                demangled,
121	                grid,
122	                block,
123	                dynamic_shared_mem_bytes,
124	                ..
125	            } => format!(
126	                "{}\\ngrid={} block={} dynamic_smem={}",
127	                dot_escape(&compact_kernel_name(demangled)),
128	                dims(*grid),
129	                dims(*block),
130	                dynamic_shared_mem_bytes,
131	            ),
132	            GraphNodeKind::Other { node_type } => dot_escape(&node_type.to_ascii_uppercase()),
133	        };
134	        let _ = writeln!(dot, "  n{index} [fillcolor=\"{fill}\", label=\"{label}\"];");
135	    }
