137	    fn write_repeated_run(
138	        &self,
139	        dot: &mut String,
140	        run_index: usize,
141	        run: RepeatedRun,
142	        indegree: &[usize],
143	        outdegree: &[usize],
144	    ) {
145	        let kernels = self.nodes[run.start..run.start + run.width]
146	            .iter()
147	            .filter(|node| matches!(&node.kind, GraphNodeKind::Kernel { .. }))
148	            .count();
149	        let instance_description = if kernels == run.width {
150	            format!("{} kernels/instance", run.width)
151	        } else {
152	            format!("{} nodes/instance · {kernels} kernels/instance", run.width)
153	        };
154	        let _ = writeln!(
155	            dot,
156	            "  subgraph cluster_repeated_{run_index} {{\n    label=\"Repeated physical block ×{} · {instance_description}\";\n    color=\"#9CA3AF\";\n    style=\"rounded,dashed\";",
157	            run.repetitions,
158	        );
159	        if run.width <= MAX_VISIBLE_REPEAT_WIDTH {
160	            for index in run.start..run.start + run.width {
161	                self.write_human_node(dot, index, indegree[index], outdegree[index]);
162	            }
163	        } else {
164	            let _ = writeln!(
165	                dot,
166	                "    r{run_index} [shape=component, fillcolor=\"#F3F4F6\", label=\"Folded repeated subgraph\\n{} nodes and {kernels} kernels per instance\\nphysical repetitions ×{}\"];",
167	                run.width, run.repetitions,
168	            );
169	        }
170	        dot.push_str("  }\n");
171	    }
