173	    fn repeated_dag_runs(&self) -> Vec<RepeatedRun> {
174	        let signatures = self
175	            .nodes
176	            .iter()
177	            .map(GraphNode::signature)
178	            .collect::<Vec<_>>();
179	        let mut candidates = Vec::new();
180	        for start in 0..signatures.len() {
181	            let max_width = (signatures.len() - start) / 3;
182	            let mut primitive_widths = Vec::new();
183	            for width in 2..=max_width {
184	                let first = &signatures[start..start + width];
185	                if signatures[start + width..start + 2 * width] != *first
186	                    || signatures[start + 2 * width..start + 3 * width] != *first
187	                {
188	                    continue;
189	                }
190	                let mut repetitions = 3usize;
191	                while start + (repetitions + 1) * width <= signatures.len()
192	                    && signatures[start + repetitions * width..start + (repetitions + 1) * width]
193	                        == *first
194	                {
195	                    repetitions += 1;
196	                }
197	                let mut candidate = None;
198	                for repetitions in (3..=repetitions).rev() {
199	                    let run = RepeatedRun {
200	                        start,
201	                        width,
202	                        repetitions,
203	                    };
204	                    if self.is_repeated_dag(run) {
205	                        candidate = Some(run);
206	                        break;
207	                    }
208	                }
209	                let Some(candidate) = candidate else {
210	                    continue;
211	                };
212	                let bundled_primitive = primitive_widths.iter().copied().any(|primitive_width| {
213	                    width % primitive_width == 0
214	                        && first
215	                            .chunks_exact(primitive_width)
216	                            .all(|chunk| chunk == &first[..primitive_width])
217	                });
218	                if bundled_primitive {
219	                    continue;
220	                }
221	                primitive_widths.push(width);
222	                candidates.push(candidate);
223	            }
224	        }
225	        let runs = select_non_overlapping_runs(candidates);
226	        let saved = runs.iter().map(|run| run.saved_nodes()).sum::<usize>();
227	        if saved.saturating_mul(2) >= self.nodes.len() {
228	            runs
229	        } else {
230	            Vec::new()
231	        }
232	    }
233	
234	    fn is_repeated_dag(&self, run: RepeatedRun) -> bool {
235	        let mut internal = vec![Vec::new(); run.repetitions];
236	        let mut boundaries = vec![Vec::new(); run.repetitions - 1];
237	        for edge in &self.edges {
238	            let from = repeated_node_position(edge.from, run);
239	            let to = repeated_node_position(edge.to, run);
240	            match (from, to) {
241	                (Some((from_copy, from_offset)), Some((to_copy, to_offset)))
242	                    if from_copy == to_copy =>
243	                {
244	                    internal[from_copy].push((
245	                        from_offset,
246	                        to_offset,
247	                        edge.from_port,
248	                        edge.to_port,
249	                        edge.dependency_type,
250	                    ));
251	                }
252	                (Some((from_copy, from_offset)), Some((to_copy, to_offset)))
253	                    if from_copy + 1 == to_copy =>
254	                {
255	                    boundaries[from_copy].push((
256	                        from_offset,
257	                        to_offset,
258	                        edge.from_port,
259	                        edge.to_port,
260	                        edge.dependency_type,
261	                    ));
262	                }
263	                (Some(_), Some(_)) => return false,
264	                (None, Some((to_copy, _))) if to_copy != 0 => return false,
265	                (Some((from_copy, _)), None) if from_copy + 1 != run.repetitions => return false,
266	                _ => {}
267	            }
268	        }
269	        for edges in internal.iter_mut().chain(boundaries.iter_mut()) {
270	            edges.sort_unstable();
271	        }
272	        boundaries.iter().all(|edges| !edges.is_empty())
273	            && internal.windows(2).all(|pair| pair[0] == pair[1])
274	            && boundaries.windows(2).all(|pair| pair[0] == pair[1])
275	    }
276	}
