297	fn repeated_node_position(index: usize, run: RepeatedRun) -> Option<(usize, usize)> {
298	    (run.start..run.end()).contains(&index).then(|| {
299	        let offset = index - run.start;
300	        (offset / run.width, offset % run.width)
301	    })
302	}
