304	fn select_non_overlapping_runs(mut candidates: Vec<RepeatedRun>) -> Vec<RepeatedRun> {
305	    candidates.sort_unstable_by_key(|run| (run.end(), run.start, run.width, run.repetitions));
306	    let mut best_savings = vec![0usize; candidates.len() + 1];
307	    let mut take = vec![false; candidates.len()];
308	    let mut compatible_count = vec![0usize; candidates.len()];
309	    for (index, &candidate) in candidates.iter().enumerate() {
310	        let compatible = candidates[..index].partition_point(|run| run.end() <= candidate.start);
311	        compatible_count[index] = compatible;
312	        let with_candidate = best_savings[compatible] + candidate.saved_nodes();
313	        if with_candidate > best_savings[index] {
314	            best_savings[index + 1] = with_candidate;
315	            take[index] = true;
316	        } else {
317	            best_savings[index + 1] = best_savings[index];
318	        }
319	    }
320	
321	    let mut selected = Vec::new();
322	    let mut cursor = candidates.len();
323	    while cursor > 0 {
324	        let index = cursor - 1;
325	        if take[index] {
326	            selected.push(candidates[index]);
327	            cursor = compatible_count[index];
328	        } else {
329	            cursor -= 1;
330	        }
331	    }
332	    selected.sort_unstable_by_key(|run| run.start);
333	    selected
334	}
335	
336	fn run_membership(index: usize, runs: &[RepeatedRun]) -> Option<(usize, usize, usize)> {
337	    runs.iter().enumerate().find_map(|(run_index, &run)| {
338	        repeated_node_position(index, run).map(|(copy, offset)| (run_index, copy, offset))
339	    })
340	}
341	
342	fn project_node(
343	    index: usize,
344	    membership: Option<(usize, usize, usize)>,
345	    runs: &[RepeatedRun],
346	) -> HumanNodeId {
347	    let Some((run_index, _, offset)) = membership else {
348	        return HumanNodeId::Original(index);
349	    };
350	    let run = runs[run_index];
351	    if run.width <= MAX_VISIBLE_REPEAT_WIDTH {
352	        HumanNodeId::Original(run.start + offset)
353	    } else {
354	        HumanNodeId::RepeatedSummary(run_index)
355	    }
356	}
