358	fn write_human_edge(dot: &mut String, edge: HumanEdge) {
359	    dot.push_str("  ");
360	    write_human_node_id(dot, edge.from);
361	    dot.push_str(" -> ");
362	    write_human_node_id(dot, edge.to);
363	    let special = edge.from_port != 0 || edge.to_port != 0 || edge.dependency_type != 0;
364	    match (edge.after_repetitions, special) {
365	        (None, false) => dot.push_str(";\n"),
366	        (Some(repetitions), false) => {
367	            let _ = writeln!(dot, " [label=\"after ×{repetitions}\", fontsize=9];");
368	        }
369	        (after, true) => {
370	            let prefix = after
371	                .map(|repetitions| format!("after ×{repetitions} · "))
372	                .unwrap_or_default();
373	            let _ = writeln!(
374	                dot,
375	                " [color=\"#2563EB\", style=dashed, label=\"{prefix}{} · port {}→{}\", fontsize=8];",
376	                dependency_type_name(edge.dependency_type),
377	                edge.from_port,
378	                edge.to_port,
379	            );
380	        }
381	    }
382	}
