384	fn write_human_node_id(dot: &mut String, node: HumanNodeId) {
385	    match node {
386	        HumanNodeId::Original(index) => {
387	            let _ = write!(dot, "n{index}");
388	        }
389	        HumanNodeId::RepeatedSummary(index) => {
390	            let _ = write!(dot, "r{index}");
391	        }
392	    }
393	}
