395	fn node_color(indegree: usize, outdegree: usize) -> &'static str {
396	    if indegree == 0 {
397	        "#DCEEFF"
398	    } else if outdegree == 0 {
399	        "#E8DEFF"
400	    } else if indegree > 1 {
401	        "#FFE8C2"
402	    } else if outdegree > 1 {
403	        "#E3F6E8"
404	    } else {
405	        "#F5F5F5"
406	    }
407	}
