409	fn compact_kernel_name(name: &str) -> String {
410	    const MAX_CHARS: usize = 72;
411	
412	    if name.contains("internal::gemvx::kernel") {
413	        return "cuBLAS GEMV".to_owned();
414	    }
415	    let signature = name.rsplit_once('(').map_or(name, |(name, _)| name);
416	    let mut compact = String::with_capacity(signature.len());
417	    let mut template_depth = 0usize;
418	    for ch in signature.chars() {
419	        match ch {
420	            '<' => {
421	                if template_depth == 0 {
422	                    compact.push_str("<…>");
423	                }
424	                template_depth += 1;
425	            }
426	            '>' if template_depth > 0 => template_depth -= 1,
427	            _ if template_depth == 0 => compact.push(ch),
428	            _ => {}
429	        }
430	    }
431	    let leaf = compact.rsplit("::").next().unwrap_or(&compact);
432	    if leaf.chars().count() <= MAX_CHARS {
433	        return leaf.to_owned();
434	    }
435	    let prefix = leaf.chars().take(MAX_CHARS - 1).collect::<String>();
436	    format!("{prefix}…")
437	}
