137	    fn write_repeated_run(
138	        &self,
139	        dot: &mut String,
140	        run_index: usize,
141	        run: RepeatedRun,
142	        indegree: &[usize],
143	        outdegree: &[usize],
144	    ) {
145	        let kernels = self.nodes[run.start..run.start + run.width]
146	            .iter()
147	            .filter(|node| matches!(&node.kind, GraphNodeKind::Kernel { .. }))
148	            .count();
149	        let instance_description = if kernels == run.width {
150	            format!("{} kernels/instance", run.width)
151	        } else {
